const stripHtml = (value) => String(value ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const value = (keys) => keys.map((key) => $json[key]).find((item) => item !== undefined && item !== null && item !== '');
const body = value(['textPlain', 'text', 'body', 'snippet', 'html']) ?? '';
const subject = value(['subject']) ?? 'Not specified';
const sender = value(['from', 'sender']) ?? 'Not specified';
const date = value(['date', 'internalDate']) ?? 'Not specified';
const messageId = value(['id', 'messageId', 'message_id']) ?? 'Not specified';
const emailLink = value(['threadUrl', 'webLink', 'link']) ?? 'Not specified';
const cleanBody = stripHtml(body).slice(0, 12000) || 'Not specified';
return [{ json: { email_subject: subject, email_from: sender, email_date: date, email_message_id: messageId, email_link: emailLink, email_body: cleanBody, ai_input: JSON.stringify({ subject, from: sender, date, body: cleanBody }) } }];

parameters.prompt:
=You extract opportunity data from email. Return JSON only with: is_opportunity (boolean), opportunity_type, title, organization, deadline, priority, priority_score, summary, action_required, skills_requirements (array), location_mode, tags (array), confidence (number 0 to 1). An opportunity is a genuine job, internship, hackathon, fellowship, competition, apprenticeship, scholarship, volunteering, AI/ML, software, technology, career, or learning opportunity. Reject receipts, security notices, generic promotions, and unrelated newsletters. Ground every fact only in the provided email. Never invent deadlines, organization, requirements, links, salaries, eligibility, or locations. Use Not specified for absent text facts. deadline must be YYYY-MM-DD only if an explicit unambiguous date appears, otherwise Not specified. priority: HIGH 8-10 for strongly relevant/actionable/urgent, MEDIUM 4-7 for relevant but less urgent, LOW 1-3 for weak or informational. Confidence is extraction/classification confidence, not legitimacy.

EMAIL:
{{ $json.ai_input }}

parameters.jsCode:
const source = $json;
const text = source.message?.content ?? source.content ?? source.text ?? source.choices?.[0]?.message?.content ?? '';
let parsed;
try { parsed = typeof text === 'string' ? JSON.parse(text) : text; } catch { throw new Error('OpenAI did not return valid JSON. Inspect OpenAI Analysis output and retry.'); }
if (!parsed || typeof parsed.is_opportunity !== 'boolean') throw new Error('AI output is missing is_opportunity.');
const cleanText = (value) => typeof value === 'string' && value.trim() ? value.trim() : 'Not specified';
const arrayText = (value) => Array.isArray(value) ? value.map(cleanText).join(', ') : cleanText(value);
const score = Math.min(10, Math.max(1, Number(parsed.priority_score) || 1));
const confidence = Math.min(1, Math.max(0, Number(parsed.confidence) || 0));
const original = $('Clean Email Data').item.json;
return [{ json: { ...parsed, opportunity_type: cleanText(parsed.opportunity_type), title: cleanText(parsed.title), organization: cleanText(parsed.organization), deadline: cleanText(parsed.deadline), priority: ['HIGH','MEDIUM','LOW'].includes(parsed.priority) ? parsed.priority : 'LOW', priority_score: score, summary: cleanText(parsed.summary), action_required: cleanText(parsed.action_required), skills_requirements: arrayText(parsed.skills_requirements), location_mode: cleanText(parsed.location_mode), tags: arrayText(parsed.tags), confidence, ...original, processed_at: new Date().toISOString() } }];
